<script>
 import {onMount,tick} from 'svelte';
 import WindowControls from './WindowControls.svelte';
 import {imageCaptureWindow,imageCaptureCapabilities,imageCaptureVisibleImages,imageCaptureFixture,IMAGE_CAPTURE_SCAN_SOURCE} from './image-capture-state.js';
 import {imageCaptureMenus} from './image-capture-menus.js';
 import {createImageCaptureNativeView} from './image-capture-native-view.js';
 import './image-capture.css';
 let {window,state: imageCaptureState,profile,windowId=window?.id,getFile,execute,registerView,available=true,active=true,controls={}}=$props();
 let root=$state(null),message=$state('');let originalState,originalProfile,originalWindow,originalId,retired=false,facade;
 const session=$derived(imageCaptureWindow(imageCaptureState,windowId)),cap=$derived(imageCaptureCapabilities(profile)),device=$derived(imageCaptureState.devices.find(row=>row.id===session?.deviceId)),images=$derived(imageCaptureVisibleImages(imageCaptureState,session)),selected=$derived(images.find(row=>session?.selectedIds.includes(row.id))),menus=$derived(imageCaptureMenus({state: imageCaptureState,profile,windowId})),menu=$derived(menus.find(row=>row.id===session?.menu));
 function current(){return !retired&&root?.isConnected&&imageCaptureState===originalState&&profile===originalProfile&&window===originalWindow&&windowId===originalId;}
 async function command(suffix,payload={}){if(!current()||!available||!active)return;const response=await execute(`imagecapture.${suffix}`,{windowId},payload);if(current())message=response?.status==='applied'?'':response?.error?.message??'The local image operation is unavailable.';return response;}
 async function menuAction(item){if(!item.enabled||!item.request||!current())return;const response=await execute(item.request.command,item.request.target,item.request.payload);if(current()){message=response?.status==='applied'?'':response?.error?.message??'The menu operation is unavailable.';if(response?.status==='applied'&&session?.menu)command('sheet',{menu:null});}}
 function select(event,image){const ids=event.metaKey||event.ctrlKey?session.selectedIds.includes(image.id)?session.selectedIds.filter(id=>id!==image.id):[...session.selectedIds,image.id]:[image.id];command('select',{ids});}
 function options(patch){command('scanOptions',{...session.scanOptions,...patch});}
 function crop(name,value){options({crop:{...session.scanOptions.crop,[name]:Number(value)}});}
 function keyboard(event){if(event.key==='Escape'){event.preventDefault();command('sheet',{sheet:null,menu:null});return;}if(event.target.matches('input,select,textarea'))return;const modifier=cap.windows?event.ctrlKey:event.metaKey;if(modifier&&event.key.toLowerCase()==='a'&&device?.kind==='camera'){event.preventDefault();command('select',{ids:images.map(row=>row.id)});}if(event.key==='Delete'||event.key==='Backspace'){event.preventDefault();command('delete',{confirm:false});}}
 const date=value=>new Date(value).toISOString().slice(0,16).replace('T',' ')+' UTC';
 const size=content=>Math.round((content.length-content.indexOf(',')-1)*.75/1024)+' KB';
 onMount(()=>{originalState=imageCaptureState;originalProfile=profile;originalWindow=window;originalId=windowId;facade=createImageCaptureNativeView({getRoot:()=>root,getState:()=>imageCaptureState,getProfile:()=>profile,getWindow:()=>window,windowId,available:()=>current()&&available&&active,tick});registerView?.(windowId,facade);return()=>{retired=true;facade.destroy();registerView?.(originalId,null,facade);};});
</script>
<section bind:this={root} class="image-capture-app" class:classic={cap.classic} class:golden={cap.golden} class:windows={cap.windows} data-image-capture-window-id={windowId} data-profile={typeof profile==='string'?profile:profile.id} role="region" aria-label={cap.label} tabindex="0" onkeydown={keyboard}>
 {#if session}
 <header class="image-capture-titlebar">{#if !cap.windows}<WindowControls active={active} onclose={()=>command('window.close')} onminimize={controls.onminimize} onzoom={controls.onzoom} onfullscreen={controls.onfullscreen} fullScreen={controls.fullScreen} zoomed={controls.zoomed}/>{/if}<strong>{cap.label}</strong><span>{device?.name}</span></header>
 {#if cap.windows||cap.golden}<p class="image-capture-disclosure">{cap.availability}</p>{/if}
 <nav class="image-capture-menus" aria-label="Image Capture menus">{#each menus as group}<button data-image-capture-control={`menu:${group.id}`} disabled={!available||!active||!group.enabled} aria-expanded={session.menu===group.id} onclick={()=>command('sheet',{menu:session.menu===group.id?null:group.id})}>{group.label}</button>{/each}</nav>
 {#if menu}<div class="image-capture-menu" role="menu" aria-label={menu.label}>{#each menu.children as item}<button role={item.checked!==undefined?'menuitemcheckbox':'menuitem'} aria-checked={item.checked} data-image-capture-control={`menu-item:${item.id}`} disabled={!item.enabled} onclick={()=>menuAction(item)}><span>{item.checked?'✓ ':''}{item.label}</span><kbd>{item.shortcut??''}</kbd></button>{/each}</div>{/if}
 <div class="image-capture-body" inert={!available||!active||!!session.sheet}>
 <aside class="image-capture-sidebar"><h3>DEVICES</h3>{#each imageCaptureState.devices.filter(row=>!row.shared) as row}<button class:selected={session.deviceId===row.id} data-image-capture-control={`device:${row.id}`} onclick={()=>command('device',{deviceId:row.id})}><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="7" width="18" height="13" rx="2"/><circle cx="12" cy="13.5" r="4"/><path d="M7 7V4h8v3"/></svg><span>{row.name}<small>{row.connected?'Connected locally':'Disconnected'}</small></span></button>{/each}<h3>SHARED</h3>{#each imageCaptureState.devices.filter(row=>row.shared) as row}<button class:selected={session.deviceId===row.id} data-image-capture-control={`device:${row.id}`} onclick={()=>command('device',{deviceId:row.id})}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 13h18v7H3zM3 13l4-8h11l3 8M7 17h10"/></svg><span>{row.name}<small>{row.connected?'Local flatbed':'Disconnected'}</small></span></button>{/each}<div class="image-capture-device-settings"><button data-image-capture-control="device:configuration" onclick={()=>command('sheet',{sheet:'device'})}>Device Configuration…</button>{#if device?.kind==='camera'}<label><input type="checkbox" data-image-capture-control="deleteAfterImport" checked={session.deleteAfterImport} onchange={event=>command('settings',{deleteAfterImport:event.currentTarget.checked})}/>Delete after import</label>{/if}<p>Fictional devices only.<br/>No hardware is accessed.</p></div></aside>
 <main class="image-capture-main">
 {#if device?.kind==='camera'}
 {#if !cap.classic}<div class="image-capture-toolbar"><div><strong>Image Capture</strong><small>{images.length} items</small></div><button data-image-capture-control="list" aria-label="View as list" class:selected={session.viewMode==='list'} onclick={()=>command('settings',{viewMode:'list'})}>☷</button><button data-image-capture-control="grid" aria-label="View as thumbnails" class:selected={session.viewMode==='grid'} onclick={()=>command('settings',{viewMode:'grid'})}>▦</button><button data-image-capture-control="rotate" aria-label="Rotate image left" disabled={!session.selectedIds.length} onclick={()=>command('rotate',{direction:'left'})}>↶</button><button data-image-capture-control="delete" aria-label="Delete selected images" disabled={!session.selectedIds.length} onclick={()=>command('delete',{confirm:false})}>⌫</button><input type="range" data-image-capture-control="thumbnailSize" aria-label="Thumbnail size" min="48" max="160" value={session.thumbnailSize} oninput={event=>command('settings',{thumbnailSize:Number(event.currentTarget.value)})}/></div>{/if}
 <div class="image-capture-content" data-image-capture-area="content">{#if session.viewMode==='list'}<table aria-label="Images on fictional camera"><thead><tr><th aria-label="Thumbnail"></th><th>Name</th><th>Kind</th><th>Date</th><th>File Size</th><th>Width</th><th>Height</th></tr></thead><tbody>{#each images as image}<tr class:selected={session.selectedIds.includes(image.id)}><td><button data-image-capture-control={`image:${image.id}`} aria-label={`Select ${image.name}`} aria-pressed={session.selectedIds.includes(image.id)} onclick={event=>select(event,image)}><img src={imageCaptureFixture(image).content} alt={image.name} style:width={`${session.thumbnailSize}px`} style:transform={`rotate(${image.rotation*90}deg)`}/></button></td><td><button onclick={event=>select(event,image)}>{image.name}{image.importedFileIds.length?' ✓':''}</button></td><td>PNG</td><td>{date(image.takenAt)}</td><td>{size(imageCaptureFixture(image).content)}</td><td>{imageCaptureFixture(image).width}</td><td>{imageCaptureFixture(image).height}</td></tr>{/each}</tbody></table>{:else}<div class="image-capture-grid">{#each images as image}<button class:selected={session.selectedIds.includes(image.id)} data-image-capture-control={`image:${image.id}`} aria-pressed={session.selectedIds.includes(image.id)} onclick={event=>select(event,image)}><img src={imageCaptureFixture(image).content} alt={image.name} style:width={`${session.thumbnailSize}px`} style:transform={`rotate(${image.rotation*90}deg)`}/><span>{image.name}</span></button>{/each}</div>{/if}{#if !images.length}<p class="image-capture-empty">No images remain on the fictional camera.</p>{/if}</div>
 {#if selected}<div class="image-capture-selected-preview"><img data-image-capture-preview src={imageCaptureFixture(selected).content} alt={`Preview of ${selected.name}`} style:transform={`rotate(${selected.rotation*90}deg)`}/><span>{selected.name} · actual authored PNG pixels</span></div>{/if}
 {#if cap.classic}<div class="image-capture-classic-tools"><button data-image-capture-control="list" aria-label="View as list" onclick={()=>command('settings',{viewMode:'list'})}>☷</button><button data-image-capture-control="grid" aria-label="View as thumbnails" onclick={()=>command('settings',{viewMode:'grid'})}>▦</button><button data-image-capture-control="rotate" aria-label="Rotate left" disabled={!session.selectedIds.length} onclick={()=>command('rotate',{direction:'left'})}>↶</button><button data-image-capture-control="delete" aria-label="Delete selected images" disabled={!session.selectedIds.length} onclick={()=>command('delete',{confirm:false})}>⌫</button><input type="range" data-image-capture-control="thumbnailSize" aria-label="Thumbnail size" min="48" max="160" value={session.thumbnailSize} oninput={event=>command('settings',{thumbnailSize:Number(event.currentTarget.value)})}/></div>{/if}
 <footer class="image-capture-actions"><label>Import To: <select data-image-capture-control="destination" value={session.destination} onchange={event=>command('settings',{destination:event.currentTarget.value})}><option value="documents">Documents</option><option value="desktop">Desktop</option><option value="downloads">Downloads</option></select></label><span></span><button data-image-capture-control="import" disabled={!device.connected||!session.selectedIds.length} onclick={()=>command('import')}>{cap.importLabel}</button><button data-image-capture-control="importAll" disabled={!device.connected||!images.length} onclick={()=>command('import',{all:true})}>{cap.importLabel} All</button></footer>
 {:else}
 <div class="image-capture-scanner-toolbar"><strong>{device?.name}</strong><button data-image-capture-control="details" onclick={()=>command('settings',{showDetails:!session.showDetails})}>{session.showDetails?'Hide':'Show'} Details</button></div>
 <div class="image-capture-scan-workspace" data-image-capture-area="content"><div class="image-capture-flatbed">{#if session.preview||!session.resultFileIds.length||getFile?.(session.resultFileIds[0])}<img data-image-capture-preview src={session.preview?.content??(session.resultFileIds.length?getFile(session.resultFileIds[0]).content:IMAGE_CAPTURE_SCAN_SOURCE)} alt={session.preview?'Genuinely rendered scan overview':session.resultFileIds.length?'Actual scanner result stored in Files':'Authored local image on the fictional scanner bed'}/><small>{session.preview?`${session.preview.width} × ${session.preview.height} rendered pixels`:session.resultFileIds.length?'Actual scanner result · original Files bytes':'Authored flatbed source · click Overview to apply options'}</small>{:else}<p role="alert">The actual scanner result File is unavailable.</p>{/if}</div>
 {#if session.showDetails}<div class="image-capture-scan-options"><label>Kind: <select data-image-capture-control="scan:kind" value={session.scanOptions.kind} onchange={event=>options({kind:event.currentTarget.value})}><option value="color">Color</option><option value="grayscale">Black &amp; White</option><option value="text">Text</option></select></label><label>Resolution: <select data-image-capture-control="scan:resolution" value={session.scanOptions.resolution} onchange={event=>options({resolution:Number(event.currentTarget.value)})}>{#each [75,150,300,600] as dpi}<option value={dpi}>{dpi} dpi · local source scale</option>{/each}</select></label><label>Scan To: <select data-image-capture-control="scan:destination" value={session.destination} onchange={event=>command('settings',{destination:event.currentTarget.value})}><option value="documents">Documents</option><option value="desktop">Desktop</option><option value="downloads">Downloads</option></select></label><label>Name: <input data-image-capture-control="scan:name" maxlength="128" value={session.scanOptions.name} onchange={event=>options({name:event.currentTarget.value})}/></label><label>Format: <select data-image-capture-control="scan:format" value={session.scanOptions.format} onchange={event=>options({format:event.currentTarget.value})}><option value="image/png">PNG</option><option value="image/jpeg">JPEG</option></select></label><label>Orientation: <select data-image-capture-control="scan:rotate" value={session.scanOptions.rotate} onchange={event=>options({rotate:Number(event.currentTarget.value)})}>{#each [0,1,2,3] as turn}<option value={turn}>{turn*90}° clockwise</option>{/each}</select></label><fieldset><legend>Custom size · normalized bed region</legend>{#each ['x','y','width','height'] as name}<label>{name}<input data-image-capture-control={`scan:crop:${name}`} type="number" min={name==='x'||name==='y'?0:.01} max="1" step=".01" value={session.scanOptions.crop[name]} onchange={event=>crop(name,event.currentTarget.value)}/></label>{/each}</fieldset><label>Image Correction: <select data-image-capture-control="scan:correction" value={session.scanOptions.correction} onchange={event=>options({correction:event.currentTarget.value})}><option value="none">None</option><option value="manual">Manual</option></select></label>{#if session.scanOptions.correction==='manual'}<label>Exposure <input type="range" data-image-capture-control="scan:exposure" min="-1" max="1" step=".1" value={session.scanOptions.exposure} onchange={event=>options({exposure:Number(event.currentTarget.value)})}/></label><label>Contrast <input type="range" data-image-capture-control="scan:contrast" min="0" max="2" step=".1" value={session.scanOptions.contrast} onchange={event=>options({contrast:Number(event.currentTarget.value)})}/></label>{/if}<p>Supported local flatbed only. No feeder, OCR or host scanner service.</p></div>{/if}</div>
 <footer class="image-capture-actions"><span>Fictional flatbed · real output pixels</span><span></span><button data-image-capture-control="overview" disabled={!device?.connected} onclick={()=>command('preview')}>Overview</button><button data-image-capture-control="scan" disabled={!device?.connected} onclick={()=>command('scan')}>Scan</button></footer>
 {/if}
 </main></div>
 <div class="image-capture-progress" data-image-capture-progress-panel hidden><progress data-image-capture-progress max="100" value="0" aria-label="Local image progress"></progress><output data-image-capture-progress-label></output><button data-image-capture-control="cancel" onclick={()=>command('cancel')}>Cancel</button></div>
 <footer class="image-capture-status" role="status">{message||session.status}{#each session.resultFileIds as fileId}<button data-image-capture-control={`reveal:${fileId}`} onclick={()=>command('reveal',{fileId})}>Show {fileId}</button>{/each}</footer>
 {#if session.sheet}<div class="image-capture-backdrop"><section class="image-capture-sheet" role="dialog" aria-modal="true" aria-label={session.sheet==='delete'?'Delete images':session.sheet==='device'?'Device Configuration':'Image Capture Help'}>{#if session.sheet==='delete'}<h2>Delete {session.selectedIds.length} image(s)?</h2><p>Only the fictional camera is changed. Existing imported Files will not be deleted.</p><button data-image-capture-control="delete:cancel" onclick={()=>command('sheet',{sheet:null})}>Cancel</button><button data-image-capture-control="delete:confirm" onclick={()=>command('delete',{confirm:true})}>Delete</button>{:else if session.sheet==='device'}<h2>{device?.name}</h2><label><input type="checkbox" data-image-capture-control="configure:connected" checked={device?.connected} onchange={event=>command('configure',{connected:event.currentTarget.checked})}/>Connected in this local scene</label><label>Connecting this device opens <select data-image-capture-control="configure:opens" value={device?.opens} onchange={event=>command('configure',{opens:event.currentTarget.value})}><option value="none">No application</option><option value="imagecapture">Image Capture</option></select></label><p>Authored configuration only. It does not change USB, a camera or a scanner.</p><button data-image-capture-control="device:done" onclick={()=>command('sheet',{sheet:null})}>Done</button>{:else}<h2>{cap.label} Help</h2><p>{cap.availability}</p><p>Select the fictional Trail Camera to preview, rotate, delete or import its genuine PNG images. Import To names real local Files folders. Delete after import and all generated Files are one atomic operation.</p><p>Select Studio Flatbed. Kind, resolution, region, orientation and correction alter actual locally rendered pixels. Overview creates no File; Scan saves the selected PNG or JPEG format. Resolution scales the authored 150dpi source and is bounded to 2048 pixels per edge.</p><p>All device configuration is local fiction. No camera, scanner, network or host filesystem is used.</p><button data-image-capture-control="help:done" onclick={()=>command('sheet',{sheet:null})}>Done</button>{/if}</section></div>{/if}
 {:else}<p role="alert">The original Image Capture session is unavailable.</p>{/if}
</section>
